<?php
require_once __DIR__ . '/../includes/db.php'; $page_title = 'Resumen'; require_once __DIR__ . '/../includes/admin-header.php';
try { $monthStart = date('Y-m-01') . 'T00:00:00Z'; $total = supabase_count('contact_messages?select=id'); $new = supabase_count('contact_messages?select=id&status=eq.new'); $month = supabase_count('contact_messages?select=id&created_at=gte.' . rawurlencode($monthStart)); $latest = supabase_request('GET', 'contact_messages?select=id,name,email,service,status,created_at&order=created_at.desc&limit=6')['data']; } catch (Throwable $e) { $total=$new=$month=0; $latest=[]; $db_error=true; }
?><section class="dashboard-content"><?php if (!empty($db_error)): ?><div class="alert error">No fue posible leer la base de datos. Verificá la configuración e importá el script SQL.</div><?php endif; ?><div class="stat-grid"><article class="stat-card"><span>✉</span><div><small>Mensajes totales</small><strong><?= $total ?></strong></div></article><article class="stat-card"><span>●</span><div><small>Mensajes nuevos</small><strong><?= $new ?></strong></div></article><article class="stat-card"><span>◷</span><div><small>Recibidos este mes</small><strong><?= $month ?></strong></div></article></div><div class="table-card"><div class="card-heading"><div><h2>Consultas recientes</h2><p>Últimos mensajes recibidos desde el sitio web.</p></div><a href="messages.php">Ver todos →</a></div><?php if ($latest): ?><div class="table-scroll"><table><thead><tr><th>Nombre</th><th>Servicio</th><th>Fecha</th><th>Estado</th></tr></thead><tbody><?php foreach ($latest as $message): ?><tr><td><strong><?= e($message['name']) ?></strong><small><?= e($message['email']) ?></small></td><td><?= e($message['service'] ?: '—') ?></td><td><?= date('d/m/Y H:i', strtotime($message['created_at'])) ?></td><td><span class="status <?= e($message['status']) ?>"><?= $message['status'] === 'new' ? 'Nuevo' : 'Leído' ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state">Todavía no hay mensajes de contacto.</div><?php endif; ?></div></section><?php require_once __DIR__ . '/../includes/admin-footer.php'; ?>
